def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, op_last = history[-1]

    my_c = 0
    opp_c = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
        if o == 'C':
            opp_c += 1
    my_d = n - my_c
    opp_d = n - opp_c
    prior = opp_c / n

    k = 10 if n >= 10 else n
    opp_d_recent = 0
    for i in range(n - k, n):
        if history[i][1] == 'D':
            opp_d_recent += 1

    opp_d_run = 0
    for m, o in reversed(history):
        if o == 'D':
            opp_d_run += 1
        else:
            break

    prev_my_d = 0
    prev_my_c = 0
    c_after_d = 0
    c_after_c = 0
    for i in range(1, n):
        m0 = history[i - 1][0]
        o1 = history[i][1]
        if m0 == 'D':
            prev_my_d += 1
            if o1 == 'C':
                c_after_d += 1
        else:
            prev_my_c += 1
            if o1 == 'C':
                c_after_c += 1
    d_after_d = prev_my_d - c_after_d

    cooperative = opp_c >= opp_d
    forgive_limit = max(2, n // 10)
    punish_limit = max(4, n // 5)

    # First D by us has not yet received a response. If the opponent looks
    # cooperative, be cautious and see whether it retaliates or forgives.
    if (my_last == 'D' and prev_my_d == 0 and prior > 0.5 and
            not (op_last == 'D' and opp_d_run >= 2 and opp_d > my_d + 1)):
        return 'C'

    # Defection streaks usually mean we should stop cooperating immediately.
    if op_last == 'D' and (opp_d_run >= 2 or opp_d_recent >= max(4, k // 2)):
        if not (my_last == 'D' and cooperative and opp_d <= forgive_limit and opp_d_run < 4):
            return 'D'

    # If a cooperative opponent punished our last D exactly once, restore CC
    # rather than locking into mutual defection.
    if (op_last == 'D' and my_d > 0 and d_after_d > 0 and c_after_d == 0 and
            cooperative and opp_d <= punish_limit):
        return 'C'

    # If we are both in a short mutual-D cycle against a nice opponent, break it.
    if (my_last == 'D' and op_last == 'D' and cooperative and
            opp_d <= punish_limit and opp_d_run < 4):
        return 'C'

    # Rare unprovoked D: often best to give one more chance to cooperate.
    if my_d == 0 and op_last == 'D' and prior > 0.75 and opp_d <= forgive_limit:
        return 'C'

    # If our D's have mostly met C, exploit aggressively.
    if c_after_d > d_after_d and c_after_d >= 1 and cooperative and op_last == 'C':
        return 'D'

    # Small random probes to discover exploitative strategies, but only while
    # the opponent looks soft and before too many own defects have happened.
    if (my_last == 'C' and op_last == 'C' and my_d < 2 and cooperative and
            opp_d <= forgive_limit and prior > 0.75 and n >= 10):
        if my_d == 0:
            if rng.random() < 0.05:
                return 'D'
        elif opp_d_recent == 0 and rng.random() < 0.004:
            return 'D'

    # If D's have mostly been punished, stay cooperative against nice opponents.
    if my_d > 0 and d_after_d > c_after_d and cooperative and opp_d <= punish_limit:
        return 'C'

    # No response evidence yet: do not open fire without a probe.
    if prev_my_d == 0 and my_d == 0 and cooperative and opp_d <= forgive_limit:
        return 'C'

    # Fallback simple expected-value heuristic.
    alpha = 1.0
    if prev_my_c > 0:
        qC = (c_after_c + prior * alpha) / (prev_my_c + alpha)
    else:
        qC = prior
    if prev_my_d > 0:
        qD = (c_after_d + prior * alpha) / (prev_my_d + alpha)
    else:
        qD = 0.0

    base = qD if my_last == 'D' else qC
    if op_last == 'C':
        p = 0.65 * base + 0.35
    else:
        p = 0.65 * base

    if opp_d_recent >= max(3, k // 2):
        p = min(p, 0.5)

    valC = 3.0 * p + (1.0 + 2.0 * qC)
    valD = 1.0 + 4.0 * p + (1.0 + 2.0 * qD)

    if valD > valC + 0.000000001:
        return 'D'
    return 'C'
